-- ====================================================================
-- Nusa Lingua — konten learning path Jawa & Sunda dari basanusa-dataset
-- DIBUAT OTOMATIS oleh scripts/generate_basanusa_migration.py — jangan diedit manual.
--
-- Sumber data: basanusa-dataset/ (hanya baris ber-sumber NusaX).
--   NusaX: Multilingual Parallel Sentiment Dataset for 10 Indonesian Local
--   Languages (EACL 2023) — https://github.com/IndoNLP/nusax
--   Lisensi CC BY-SA 4.0. Atribusi ini WAJIB disebut (README & footer aplikasi).
--   Baris kamus-sunda (KatowProject) TIDAK disertakan: lisensinya tidak
--   dinyatakan. Akibatnya sebagian lesson & soal Sunda ikut dibuang.
--
-- Prasyarat : 0001_schema.sql → 0002_storage.sql → seed.sql sudah dijalankan.
-- Aman ulang : ya (on conflict do nothing).
--
-- Isi       : 20 unit · 82 lesson · 1242 kosakata · 799 soal (cap 10 soal/lesson).
-- ====================================================================

begin;

-- ---------------------------------------------------------------------
-- Unit (order_index lanjutan setelah unit seed yang bernilai 1..2)
-- ---------------------------------------------------------------------
on conflict (id) do nothing;

-- ---------------------------------------------------------------------
-- Lesson
-- ---------------------------------------------------------------------
on conflict (id) do nothing;

-- ---------------------------------------------------------------------
-- Kosakata (inti + varian; peran & source menyimpan metadata dataset)
-- ---------------------------------------------------------------------
on conflict (id) do nothing;

-- ---------------------------------------------------------------------
-- Soal (dataset = multiple_choice; sisanya hasil generate)
-- ---------------------------------------------------------------------
on conflict (id) do nothing;

-- Kosakata lama (seed) diberi label sumber agar atribusi bisa dicek.
update public.vocabularies set source = 'seed' where source is null;

select setval(pg_get_serial_sequence('public.units', 'id'), (select max(id) from public.units));
select setval(pg_get_serial_sequence('public.lessons', 'id'), (select max(id) from public.lessons));
select setval(pg_get_serial_sequence('public.vocabularies', 'id'), (select max(id) from public.vocabularies));
select setval(pg_get_serial_sequence('public.questions', 'id'), (select max(id) from public.questions));

commit;
